    private static readonly Dictionary<(ushort Species, byte Form), TmtSpeciesEntry> BySpeciesForm =
        Entries.ToDictionary(e => (e.Species, e.Form));
    private static readonly Dictionary<ushort, TmtSpeciesEntry> ByRaw =
        Entries.GroupBy(e => e.RawSpecies).ToDictionary(g => g.Key, g => g.First());

    public static bool TryGet(ushort species, byte form, out TmtSpeciesEntry entry)
        => BySpeciesForm.TryGetValue((species, form), out entry!);

    public static bool TryGetRaw(ushort rawSpecies, out TmtSpeciesEntry entry)
        => ByRaw.TryGetValue(rawSpecies, out entry!);

    public static bool Supports(ushort species, byte form) => BySpeciesForm.ContainsKey((species, form));
